mapper.select:
select d.*, () as writable,

from ai_knowledge_document d
join ai_knowledge_base b on b.id = d.knowledge_base_id and b.del_flag = 0
where d.knowledge_base_id = #{knowledgeBaseId} and d.del_flag = 0 and 


        and d.folder_id in

            #{folder}



        and d.folder_id = #{folderId}



    and d.document_name like concat('%', #{keyword}, '%')


    and d.upload_status = #{uploadStatus}


    and d.chunk_status = #{chunkStatus}


    and d.data_status = #{dataStatus}

order by d.create_time desc, d.id desc
